// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(target != address(0) && amount > 0 && amount <= address(this).balance);
        address owner = c.owner();
        vm.deal(owner, amount);
        vm.prank(owner);
        bool ok;
        try c.sendMoney(target, amount, "") { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
